  don_next: "<strong style=\"color:var(--bnb)\">\u0421\u043B\u0435\u0434\u043D\u043E:</strong> \u0444\u0443\u043D\u043A\u0446\u0438\u0438 \u0448\u0442\u043E \u0433\u0438 \u043F\u043E\u043C\u0438\u043D\u0443\u0432\u0430\u0430\u0442 \u0441\u043E\u043F\u0441\u0442\u0432\u0435\u043D\u0438\u0442\u0435 \u0442\u0435\u0441\u0442\u043E\u0432\u0438",
