    {"title":"\u0410\u043B\u0430\u0442\u043A\u0430 \u0437\u0430 \u0437\u0430\u043C\u0435\u043D\u0430 \u2014 \u043E\u0434\u043D\u043E\u0441\u043E\u0442 \u043F\u043E\u043C\u0435\u0453\u0443 \u0434\u0432\u0435 \u0441\u0440\u0435\u0434\u0441\u0442\u0432\u0430","desc":"\u041E\u0432\u0430\u0430 \u0430\u043B\u0430\u0442\u043A\u0430 \u0433\u043E \u0441\u043B\u0435\u0434\u0438 \u043E\u0434\u043D\u043E\u0441\u043E\u0442 \u043D\u0430 \u0446\u0435\u043D\u0438\u0442\u0435 \u043D\u0430 \u0434\u0432\u0435 \u0441\u0440\u0435\u0434\u0441\u0442\u0432\u0430 \u0441\u043E \u0442\u0435\u043A\u043E\u0442 \u043D\u0430 \u0432\u0440\u0435\u043C\u0435\u0442\u043E, \u0437\u0430 \u0434\u0430 \u0432\u0438\u0434\u0438\u0442\u0435 \u043A\u0430\u0434\u0435 \u0435 \u0434\u0435\u043D\u0435\u0441 \u0432\u043E \u043D\u0435\u043E\u0434\u0430\u043C\u043D\u0435\u0448\u043D\u0438\u043E\u0442 \u043E\u043F\u0441\u0435\u0433. \u041F\u043E\u043A\u0430\u0436\u0443\u0432\u0430 \u043A\u0430\u0434\u0435 \u0435 \u043E\u0434\u043D\u043E\u0441\u043E\u0442, \u0430 \u043D\u0435 \u043A\u0430\u0434\u0435 \u045C\u0435 \u043E\u0434\u0438 \u043F\u043E\u043D\u0430\u0442\u0430\u043C\u0443."},
    {"title":"\u0418\u0437\u0431\u0435\u0440\u0435\u0442\u0435 \u0433\u043E \u0432\u0430\u0448\u0438\u043E\u0442 \u043F\u0430\u0440","desc":"\u0412\u043E \u043A\u0430\u0440\u0442\u0438\u0447\u043A\u0430\u0442\u0430 **\u041E\u0414** \u0438\u0437\u0431\u0435\u0440\u0435\u0442\u0435 \u0458\u0430 \u043C\u043E\u043D\u0435\u0442\u0430\u0442\u0430 \u0448\u0442\u043E \u0458\u0430 **\u0434\u0440\u0436\u0438\u0442\u0435**, \u0430 \u0432\u043E **\u0412\u041E** \u043C\u043E\u043D\u0435\u0442\u0430\u0442\u0430 \u0448\u0442\u043E \u0458\u0430 **\u0440\u0430\u0437\u0433\u043B\u0435\u0434\u0443\u0432\u0430\u0442\u0435** (\u0434\u043E\u043F\u0440\u0435\u0442\u0435 \u25BE). \u041E\u0434\u043D\u043E\u0441\u043E\u0442 \u043F\u043E\u043A\u0430\u0436\u0443\u0432\u0430 \u043A\u043E\u043B\u043A\u0443 \u043C\u043E\u043D\u0435\u0442\u0438 \u0412\u041E \u0434\u043E\u0431\u0438\u0432\u0430\u0442\u0435 \u0437\u0430 \u0435\u0434\u043D\u0430 \u043C\u043E\u043D\u0435\u0442\u0430 \u041E\u0414 \u043F\u043E \u0442\u0435\u043A\u043E\u0432\u043D\u0438\u0442\u0435 \u0446\u0435\u043D\u0438."},
    {"title":"\u041F\u0440\u043E\u0447\u0438\u0442\u0430\u0458\u0442\u0435 \u0458\u0430 \u0438\u0441\u0442\u043E\u0440\u0438\u0458\u0430\u0442\u0430 \u043D\u0430 \u043E\u0434\u043D\u043E\u0441\u043E\u0442","desc":"\u041B\u0435\u043D\u0442\u0430\u0442\u0430 \u0433\u043E \u043F\u043E\u043A\u0430\u0436\u0443\u0432\u0430 \u043E\u0434\u043D\u043E\u0441\u043E\u0442 \u0432\u043E \u0438\u0437\u0431\u0440\u0430\u043D\u0438\u043E\u0442 \u043F\u0435\u0440\u0438\u043E\u0434 (24h, 7d \u0438\u043B\u0438 30d). **\u041D\u0438\u0441\u043A\u043E** \u0435 \u043D\u0430\u0458\u043C\u0430\u043B\u0438\u043E\u0442 \u043E\u0434\u043D\u043E\u0441, **\u25B2 \u0412\u0440\u0432** \u0435 \u043D\u0430\u0458\u043C\u043D\u043E\u0433\u0443 \u043C\u043E\u043D\u0435\u0442\u0438 \u0412\u041E \u0448\u0442\u043E \u043C\u043E\u0436\u0435\u043B\u0435 \u0434\u0430 \u0441\u0435 \u0434\u043E\u0431\u0438\u0458\u0430\u0442 \u0437\u0430 \u0435\u0434\u043D\u0430 \u043C\u043E\u043D\u0435\u0442\u0430 \u041E\u0414, \u0430 **\u0421\u0435\u0433\u0430** \u0435 \u0434\u0435\u043D\u0435\u0448\u043D\u0438\u043E\u0442 \u043E\u0434\u043D\u043E\u0441. \u041A\u0430\u0434\u0435 \u045C\u0435 \u043E\u0434\u0438 \u043E\u0434\u043D\u043E\u0441\u043E\u0442 \u043F\u043E\u043D\u0430\u0442\u0430\u043C\u0443 \u043D\u0435 \u0441\u0435 \u0437\u043D\u0430\u0435."},
    {"title":"\u0418\u0437\u043D\u043E\u0441 \u0438 \u0440\u0435\u0437\u0443\u043B\u0442\u0430\u0442","desc":"\u0412\u043D\u0435\u0441\u0435\u0442\u0435 \u043A\u043E\u043B\u0438\u0447\u0438\u043D\u0430 \u0432\u043E \u043A\u0430\u0440\u0442\u0438\u0447\u043A\u0430\u0442\u0430 **\u041E\u0414**, \u0430 \u043F\u043E\u0434 **\u0414\u043E\u0431\u0438\u0432\u0430\u0442\u0435** \u0432\u043E \u043A\u0430\u0440\u0442\u0438\u0447\u043A\u0430\u0442\u0430 **\u0412\u041E** \u043F\u0438\u0448\u0443\u0432\u0430 \u0448\u0442\u043E \u0431\u0438 \u0434\u043E\u0431\u0438\u043B\u0435. \u041F\u043E\u0434\u043E\u043B\u0443: \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442\u0430 \u0432\u043E \u0434\u043E\u043B\u0430\u0440\u0438 \u0438 \u043E\u0434\u043D\u043E\u0441\u043E\u0442 \u0432\u043E \u0434\u0432\u0435\u0442\u0435 \u043D\u0430\u0441\u043E\u043A\u0438. \u0412\u043E **\u041D\u0410\u041F\u0420\u0415\u0414\u041D\u041E \u2014 \u0420\u0430\u0447\u043D\u0438 \u0446\u0435\u043D\u0438** \u043C\u043E\u0436\u0435\u0442\u0435 \u0441\u0430\u043C\u0438 \u0434\u0430 \u0432\u043D\u0435\u0441\u0435\u0442\u0435 \u0446\u0435\u043D\u0438 \u0437\u0430 \u0434\u0430 \u043F\u0440\u043E\u0431\u0430\u0442\u0435 \u201E\u0448\u0442\u043E \u0430\u043A\u043E\u201C. \u0421\u0435\u043A\u043E\u0433\u0430\u0448 \u043F\u0440\u043E\u0432\u0435\u0440\u0435\u0442\u0435 \u043D\u0430 \u0432\u0430\u0448\u0430\u0442\u0430 \u0431\u0435\u0440\u0437\u0430 \u043F\u0440\u0435\u0434 \u0434\u0430 \u0442\u0440\u0433\u0443\u0432\u0430\u0442\u0435, \u0431\u0438\u0434\u0435\u0458\u045C\u0438 \u0446\u0435\u043D\u0438\u0442\u0435 \u0431\u0440\u0437\u043E \u0441\u0435 \u043C\u0435\u043D\u0443\u0432\u0430\u0430\u0442."}
